  private buildQueryString(params: Record<string, QueryParamValue> = {}) {
    const queryParams = new URLSearchParams();
    Object.entries(params).forEach(([key, value]) => {
      if (value !== undefined && value !== null) {
        queryParams.append(key, String(value));
      }
    });

    const queryString = queryParams.toString();
    return queryString ? `?${queryString}` : '';
  }

  private async parseResponseBody(response: Response) {
    if (response.status === 204) {
      return null;
    }

    const contentType = response.headers?.get?.('content-type') || '';
    const shouldTryJson =
      contentType.includes('application/json') || typeof response.json === 'function';

    if (shouldTryJson) {
      const parsedJson = await response.json().catch(() => null);
      if (parsedJson !== null) {
        return parsedJson;
      }
    }

    if (typeof response.text === 'function') {
      return response.text().catch(() => '');
    }

    return null;
  }

  private extractErrorMessage(responseBody: unknown, status: number) {
    if (
      responseBody &&
      typeof responseBody === 'object' &&
      'message' in responseBody &&
      typeof (responseBody as { message: unknown }).message === 'string'
    ) {
      return (responseBody as { message: string }).message;
    }

    if (
      responseBody &&
      typeof responseBody === 'object' &&
      'error' in responseBody &&
      typeof (responseBody as { error: unknown }).error === 'string'
    ) {
      return (responseBody as { error: string }).error;
    }

    if (typeof responseBody === 'string' && responseBody.trim().length > 0) {
      return responseBody;
    }

    if (status === 429) {
      return 'Too many requests. Please wait a moment and try again.';
    }

    return `HTTP error! status: ${status}`;
  }

  // Build an Error that carries the HTTP status. We expose it both as `status` and
  // as an axios-compatible `response.status` so that route guards / callers that were
  // written against the axios error shape (e.g. RequireMSME, RequireEnterprise) can
  // detect 401/403/404 instead of silently treating an expired session as a generic
  // failure (which left users stuck on a "retry" screen with no path to re-login).
  private createHttpError(responseBody: unknown, status: number): Error {
    const error = new Error(this.extractErrorMessage(responseBody, status)) as Error & {
      status?: number;
      response?: { status: number; data?: unknown };
    };
    error.status = status;
    error.response = { status, data: responseBody };
    return error;
  }

  async request<T = ApiResponse>(endpoint: string, options: RequestInit = {}): Promise<T> {
    const url = `${API_BASE_URL}${endpoint}`;
    const headers: Record<string, string> = {};

    if (options.headers instanceof Headers) {
      options.headers.forEach((value, key) => {
        headers[key] = value;
      });
    } else if (Array.isArray(options.headers)) {
      options.headers.forEach(([key, value]) => {
        headers[key] = value;
      });
    } else if (options.headers) {
      Object.assign(headers, options.headers as Record<string, string>);
    }

    const hasContentTypeHeader = Object.keys(headers).some(
      (key) => key.toLowerCase() === 'content-type'
    );
    if (!(options.body instanceof FormData) && !hasContentTypeHeader) {
      headers['Content-Type'] = 'application/json';
    }

    const token = localStorage.getItem('token');
    const hasAuthorizationHeader = Object.keys(headers).some(
      (key) => key.toLowerCase() === 'authorization'
    );
    if (token && !hasAuthorizationHeader) {
      headers.Authorization = `Bearer ${token}`;
    }

    let response: Response;
    try {
      response = await fetch(url, {
        ...options,
        headers,
      });
    } catch (err) {
      if (isLikelyNetworkFailure(err)) {
        throw new Error(
          'Unable to reach the server. Check your internet connection and that the API URL is configured correctly, then try again.'
        );
      }
      throw err instanceof Error ? err : new Error('Request failed');
    }

    const responseBody = await this.parseResponseBody(response);

    if (!response.ok) {
      throw this.createHttpError(responseBody, response.status);
    }

    return responseBody as T;
  }

  private async requestBlob(endpoint: string, params: Record<string, QueryParamValue> = {}) {
    const url = `${API_BASE_URL}${endpoint}${this.buildQueryString(params)}`;
    const headers: Record<string, string> = {};
    const token = localStorage.getItem('token');
    if (token) {
      headers.Authorization = `Bearer ${token}`;
    }

    let response: Response;
    try {
      response = await fetch(url, {
        method: 'GET',
        headers,
      });
    } catch (err) {
      if (isLikelyNetworkFailure(err)) {
        throw new Error(
          'Unable to reach the server. Check your internet connection and that the API URL is configured correctly, then try again.'
        );
      }
      throw err instanceof Error ? err : new Error('Request failed');
    }

    if (!response.ok) {
      const errorBody = await this.parseResponseBody(response);
      throw this.createHttpError(errorBody, response.status);
    }

    return response.blob();
  }

