import React from 'react';
import { Box, Card, CardContent, Chip, Grid, LinearProgress, Stack, Typography } from '@mui/material';
import { alpha, useTheme } from '@mui/material/styles';
import { CO2E_METHODOLOGY_SUBTITLE, GHG_SCOPE_COLORS, GHG_SCOPE_HEX } from '../../constants/carbonVisualization';
import { computeEnvironmentalEquivalents } from '../../utils/sustainabilityUx';
import { DataConfidenceChip, type DataConfidenceChipProps } from './DataConfidenceChip';

export interface DashboardHeroProps {
  carbonScore: number;
  scoreLabel: string;
  scoreColor: 'success' | 'warning' | 'error' | 'default';
  carbonEmissionsKg: number;
  s1Kg: number;
  s2Kg: number;
  s3Kg: number;
  scopeSumKg: number;
  lastAssessmentLabel: string | null;
  assessmentPeriodLabel: string | null;
  forecastTCO2e: number;
  forecastCaption: string;
  hotspotDescription: string;
  dataQuality?: Pick<DataConfidenceChipProps, 'level' | 'label' | 'score' | 'hints'>;
}

function scopeBarSx(fill: string, isDark: boolean) {
  return {
    height: 8,
    borderRadius: 4,
    bgcolor: alpha(fill, isDark ? 0.22 : 0.12),
    '& .MuiLinearProgress-bar': { bgcolor: fill, borderRadius: 4 },
  };
}

export const DashboardHero: React.FC<DashboardHeroProps> = ({
  carbonScore,
  scoreLabel,
  scoreColor,
  carbonEmissionsKg,
  s1Kg,
  s2Kg,
  s3Kg,
  scopeSumKg,
  lastAssessmentLabel,
  assessmentPeriodLabel,
  forecastTCO2e,
  forecastCaption,
  hotspotDescription,
  dataQuality,
}) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';
  const barPct = (kg: number) => (scopeSumKg > 0 ? Math.round((kg / scopeSumKg) * 100) : 0);
  const footprintT = carbonEmissionsKg > 0 ? (carbonEmissionsKg / 1000).toFixed(2) : '—';
  const compliant = carbonScore >= 60;
  const equivalents = computeEnvironmentalEquivalents(carbonEmissionsKg);

  const scopeRows = [
    { key: 'scope1' as const, kg: s1Kg, label: GHG_SCOPE_COLORS.scope1.label },
    { key: 'scope2' as const, kg: s2Kg, label: GHG_SCOPE_COLORS.scope2.label },
    { key: 'scope3' as const, kg: s3Kg, label: GHG_SCOPE_COLORS.scope3.label },
  ];

  return (
    <Card
      sx={{
        border: `1px solid ${alpha(theme.palette.primary.main, isDark ? 0.35 : 0.18)}`,
        background: isDark
          ? `linear-gradient(145deg, ${theme.palette.background.paper} 0%, ${alpha(theme.palette.primary.dark, 0.12)} 100%)`
          : 'linear-gradient(135deg, #ffffff 0%, #f0fdf4 55%, #f8fafc 100%)',
      }}
    >
      <CardContent sx={{ p: { xs: 2.5, md: 3 } }}>
        <Grid container spacing={3} alignItems="center">
          <Grid item xs={12} sm={4} md={3}>
            <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: { xs: 'flex-start', sm: 'center' } }}>
              <Box sx={{ position: 'relative', display: 'inline-flex', mb: 1 }}>
                <Box
                  component="div"
                  sx={{
                    width: 112,
                    height: 112,
                    borderRadius: '50%',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    background: `conic-gradient(${theme.palette[scoreColor === 'default' ? 'primary' : scoreColor].main} ${carbonScore * 3.6}deg, ${alpha(theme.palette.divider, 0.35)} 0deg)`,
                    p: '5px',
                  }}
                  aria-hidden
                >
                  <Box
                    sx={{
                      width: '100%',
                      height: '100%',
                      borderRadius: '50%',
                      bgcolor: 'background.paper',
                      display: 'flex',
                      flexDirection: 'column',
                      alignItems: 'center',
                      justifyContent: 'center',
                    }}
                  >
                    <Typography variant="h4" component="span" sx={{ fontWeight: 800, lineHeight: 1 }}>
                      {carbonScore}
                    </Typography>
                    <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 600 }}>
                      / 100
                    </Typography>
                  </Box>
                </Box>
              </Box>
              <Chip size="small" color={scoreColor === 'default' ? 'default' : scoreColor} label={scoreLabel} />
              <Typography variant="caption" color="text.secondary" sx={{ mt: 1, textAlign: { sm: 'center' } }}>
                Carbon score
              </Typography>
            </Box>
          </Grid>

          <Grid item xs={12} sm={8} md={5}>
            <Typography variant="overline" color="text.secondary" sx={{ fontWeight: 600, letterSpacing: '0.08em' }}>
              Total footprint
            </Typography>
            <Typography variant="h3" sx={{ fontWeight: 800, letterSpacing: '-0.03em', lineHeight: 1.1 }}>
              {footprintT}
              <Typography component="span" variant="h6" color="text.secondary" sx={{ ml: 1, fontWeight: 600 }}>
                tCO₂e
              </Typography>
            </Typography>
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1.5, maxWidth: 420 }}>
              {CO2E_METHODOLOGY_SUBTITLE}
            </Typography>
            <Stack direction="row" spacing={1} useFlexGap flexWrap="wrap" sx={{ gap: 1 }}>
              <Chip
                size="small"
                color={compliant ? 'success' : 'warning'}
                label={compliant ? 'Compliant / on track' : 'Needs corrective action'}
              />
              {dataQuality ? (
                <DataConfidenceChip
                  level={dataQuality.level}
                  label={dataQuality.label}
                  score={dataQuality.score}
                  hints={dataQuality.hints}
                />
              ) : null}
              {forecastTCO2e > 0 ? (
                <Chip
                  size="small"
                  variant="outlined"
                  label={`Outlook ${forecastTCO2e.toFixed(2)} tCO₂e`}
                  title={forecastCaption}
                />
              ) : null}
            </Stack>
            {carbonEmissionsKg > 0 ? (
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1, maxWidth: 480 }}>
                Rough context: ~{equivalents.treesEquivalent} tree-years of absorption, ~
                {equivalents.carsOffRoadDays} car-days off road, or ~{equivalents.kwhEquivalent} kWh of grid electricity
                (illustrative only).
              </Typography>
            ) : null}
            {(lastAssessmentLabel || assessmentPeriodLabel) && (
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1.5 }}>
                {lastAssessmentLabel ? `Last saved: ${lastAssessmentLabel}` : 'Run Carbon Assessment to populate metrics.'}
                {assessmentPeriodLabel ? ` · Period: ${assessmentPeriodLabel}` : ''}
              </Typography>
            )}
          </Grid>

          <Grid item xs={12} md={4}>
            <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 1.5 }}>
              GHG scope mix
            </Typography>
            {scopeSumKg > 0 ? (
              <Stack spacing={1.25}>
                {scopeRows.map(({ key, kg, label }) => (
                  <Box key={key}>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 0.5 }}>
                      <Typography variant="caption" sx={{ fontWeight: 600 }}>
                        {label}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        {(kg / 1000).toFixed(2)} tCO₂e · {barPct(kg)}%
                      </Typography>
                    </Box>
                    <LinearProgress
                      variant="determinate"
                      value={barPct(kg)}
                      sx={scopeBarSx(GHG_SCOPE_HEX[key], isDark)}
                    />
                  </Box>
                ))}
              </Stack>
            ) : (
              <Typography variant="body2" color="text.secondary">
                Scope totals appear after your first saved assessment.
              </Typography>
            )}
          </Grid>
        </Grid>

        <Box
          sx={{
            mt: 2.5,
            pt: 2,
            borderTop: `1px solid ${alpha(theme.palette.divider, isDark ? 0.35 : 0.8)}`,
          }}
        >
          <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 600, display: 'block', mb: 0.5 }}>
            Hotspot insight
          </Typography>
          <Typography variant="body2" sx={{ lineHeight: 1.55 }}>
            {hotspotDescription}
          </Typography>
        </Box>
      </CardContent>
    </Card>
  );
};
